-- Only after all applicable reverse statements and restoring original triggers.
USE auxiliares;
DELIMITER $$
BEGIN NOT ATOMIC
 IF NOT ((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND ((TRIGGER_NAME='TRG_FB_CONSULTA_CONTACTO_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='10a2d0b7d0f8b76d42939bd906bc81716a1a10a49ac034b730809c6515051891') OR (TRIGGER_NAME='TRG_FB_CONSULTAS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='243d687db5f3b40ed5dc35d0cf4021e24422d4644522c543cee60902914e7d44') OR (TRIGGER_NAME='TRG_FB_CONSULTAS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='3f00088fdfc46737690cb7962eb8086b463bafd2bb33f25659bfac85a0d5573c') OR (TRIGGER_NAME='TRG_FB_CONSULTA_CONTACTO_EDICION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='c97af48e1b723e38c69a008c7f10e93d6e754e5ac35d24ba6075ffe16467184e') OR (TRIGGER_NAME='TRG_FB_CONSULTAS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='b0ce7f917a2c1efebf61fb7a487d952820e7835185b40dd9b74e9e2ac0ab6579') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='a36c04bfdccc633669198cd9e922c30287d1159c4ed8baa47c03ec565d8c8c35') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='79396df60fd69a3cc91a4a0ea6cccb25434f12c8c7d97ffecc1b5271f6666242') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='96aff3c7d2003e6233b9e2d5902f70096fc448f1df6fd626060acc2abe45e09d') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='941690ac1ca1e5899ff67f5604c6cc323fb9570d17b92d6ba6e3067c388b3eed') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='5c104077436a10811a206ebfe318ce17455349bfc834db15630c5bac0b52a5cc') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='86f7ad7f4209f3c654615fe43c308782b9a20b93760a1e1472001117b10ed0c4')))=11) OR NOT ((SELECT COUNT(*) FROM FB_CIU_CONSULTAS_WEB)=0 AND (SELECT COUNT(*) FROM FB_PERSONAS)=0 AND (SELECT COUNT(*) FROM FB_CONTACTOS)=0 AND (SELECT COUNT(*) FROM FB_CONTACTOS_HISTORIAL)=0 AND (SELECT COUNT(*) FROM FB_DOMICILIOS)=0 AND (SELECT COUNT(*) FROM FB_DOMICILIOS_HISTORIAL)=0 AND (SELECT COUNT(*) FROM FB_VINCULOS_DECLARADOS)=0 AND (SELECT COUNT(*) FROM FB_CONSULTAS_HISTORIAL)=0) OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND COLUMN_NAME IN ('DOCUMENTO_IDENTIDAD_UNICA','VERIFICACION_CP_JSON','REFERENCIAS_CP_JSON'))<>0 OR (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('FB_CONSULTAS_IDEMPOTENCIA','FB_MODELO_REVISION'))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_RECUPERACION_INCOMPLETA'; END IF;
END$$
DELIMITER ;
DROP TRIGGER IF EXISTS `TRG_71_GUARD_FB_CIU_CONSULTAS_WEB_I`;
